python - <<'PY'
from more_itertools import interleave_evenly, sliced, numeric_range
from decimal import Decimal
from fractions import Fraction
from datetime import datetime, timedelta
from itertools import product

for inputs in ([], [[], []], [[], [1, 2], []]):
    expected = [item for seq in inputs for item in seq]
    assert list(interleave_evenly(inputs)) == expected
    assert list(interleave_evenly(inputs, lengths=list(map(len, inputs)))) == expected
assert list(interleave_evenly([iter(()), iter(())], lengths=[0, 0])) == []
for strict in (False, True):
    for seq in ([], [1, 2, 3]):
        try:
            sliced(seq, -1, strict=strict)
        except ValueError:
            pass
        else:
            raise AssertionError('negative size accepted')
assert list(sliced([1, 2], 0)) == []

for start, stop, step in product(range(-5, 6), range(-5, 6), (-3, -1, 1, 3)):
    r = numeric_range(start, stop, step)
    assert list(reversed(r)) == list(range(start, stop, step))[::-1]
for convert in (float, Decimal, Fraction):
    for start, stop, step in product(('-1.2', '0', '0.3'), ('-1', '0', '1.1'), ('-0.3', '0.1', '0.3')):
        r = numeric_range(convert(start), convert(stop), convert(step))
        assert list(reversed(r)) == list(r)[::-1], (start, stop, step)
for step in (timedelta(days=1), timedelta(days=-1)):
    for stop in (datetime(2020, 1, 1), datetime(2020, 1, 5)):
        r = numeric_range(datetime(2020, 1, 3), stop, step)
        assert list(reversed(r)) == list(r)[::-1]
print('All targeted regression checks passed.')
